INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000029','d7301030-2026-4000-8001-000000000003','¿Qué nutrientes usan de forma destacada la vía linfática tras absorción intestinal?','Los vasos linfáticos intestinales participan en el transporte de lípidos absorbidos.','[{"text":"Determinados lípidos y vitaminas liposolubles","correct":true},{"text":"Todos los aminoácidos exclusivamente","correct":false},{"text":"Solo agua sin solutos","correct":false},{"text":"Todos los monosacáridos exclusivamente","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/21-1-anatomy-of-the-lymphatic-and-immune-systems',9,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/21-1-anatomy-of-the-lymphatic-and-immune-systems"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000030','d7301030-2026-4000-8001-000000000003','Se observa hinchazón tras una alteración del drenaje. ¿Qué razonamiento es correcto?','Una alteración linfática puede favorecer acumulación de líquido; un hallazgo aislado no determina toda la causa.','[{"text":"Toda hinchazón demuestra una única causa linfática","correct":false},{"text":"La hinchazón excluye problemas circulatorios","correct":false},{"text":"No es necesario recoger contexto","correct":false},{"text":"El drenaje puede contribuir, pero hay que valorar otras causas","correct":true}]'::jsonb,2,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/21-1-anatomy-of-the-lymphatic-and-immune-systems',10,'clinical_case','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/21-1-anatomy-of-the-lymphatic-and-immune-systems"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_topics (id,unit_id,name,slug,description,display_order,content_language,translation_mode,is_active) VALUES ('d7301030-2026-4000-8001-000000000004','d7301030-2026-4000-8000-000000000002','Genética y herencia: interpretar sin determinismo','es-s1-final-genes','Distinguir ADN, cromosoma, alelo, genotipo y fenotipo; resolver cruces mendelianos sencillos explicando sus límites.',33,'es','none',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_lessons (id,topic_id,title,summary,content,key_points,source_files,display_order,validation_status,is_published) VALUES ('d7301030-2026-4000-8002-000000000004','d7301030-2026-4000-8001-000000000004','Genética y herencia: interpretar sin determinismo','Distinguir ADN, cromosoma, alelo, genotipo y fenotipo; resolver cruces mendelianos sencillos explicando sus límites.','### Objetivos

Distinguir ADN, cromosoma, alelo, genotipo y fenotipo; resolver cruces mendelianos sencillos explicando sus límites.

### Niveles de información

Los cromosomas contienen ADN. Un gen es una región de información genética; un alelo es una variante de un locus. Genotipo describe la constitución genética y fenotipo las características observables, que pueden depender también del ambiente.

### Cruces sencillos

En un modelo autosómico con dominancia completa, AA y Aa expresan el rasgo dominante y aa el recesivo. Heterocigoto significa dos alelos distintos; homocigoto, iguales. Dominante no significa frecuente, mejor ni más saludable.

### Probabilidad y límites

Un cruce Aa por Aa produce probabilidades de un cuarto AA, mitad Aa y un cuarto aa para cada descendiente. No obliga a que una familia con cuatro hijos tenga exactamente ese reparto. La codominancia expresa ambos alelos, como IA e IB en el sistema ABO; muchos rasgos son poligénicos y no siguen un modelo de un solo gen.

### Conceptos para explicar sin mirar

- Un alelo es una variante genética en un locus; no equivale a un cromosoma completo.
- El genotipo describe la información genética; el fenotipo es su expresión observable en un contexto.
- La heterocigosis implica dos alelos distintos en un mismo locus.
- La homocigosis implica dos alelos iguales; no indica por sí sola salud o enfermedad.
- En el modelo simple, el rasgo recesivo se expresa en homocigosis aa.
- El cuadro de combinaciones da AA, Aa, Aa y aa: una de cuatro es aa.
- La probabilidad se aplica a cada combinación, no garantiza una distribución exacta en pocos casos.
- En codominancia ambos alelos se expresan, como IA e IB en el grupo AB.
- Muchos rasgos dependen de varios genes y pueden estar influidos por el ambiente.
- La dominancia es una relación de expresión; no equivale a frecuencia o valor biológico.

### Comprobación

Resuelve el cuestionario sin consultar el texto. Justifica tu elección y explica por qué las otras opciones no encajan. Si confundes dos conceptos, compáralos en una frase y vuelve a probar en otra sesión.

Material original de entrenamiento; no es un examen ni un apunte oficial de UVic.','["Niveles de información","Cruces sencillos","Probabilidad y límites"]'::jsonb,'[{"url":"https://www.uvic.cat/es/assignatura/4405","label":"UVic-UCC · plan docente y alcance curricular","verified_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance","label":"OpenStax · texto académico abierto","verified_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division","label":"OpenStax · texto académico abierto","verified_at":"2026-10-30"}]'::jsonb,1,'source_validated',true) ON CONFLICT(id) DO NOTHING;
