INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000034','d7301030-2026-4000-8001-000000000004','¿Qué significa homocigoto en un locus?','La homocigosis implica dos alelos iguales; no indica por sí sola salud o enfermedad.','[{"text":"Poseer exclusivamente ARN","correct":false},{"text":"Poseer dos alelos iguales","correct":true},{"text":"Poseer dos alelos distintos","correct":false},{"text":"Carecer de ADN","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division',4,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance","https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000035','d7301030-2026-4000-8001-000000000004','En dominancia completa, ¿qué genotipo expresa el rasgo recesivo?','En el modelo simple, el rasgo recesivo se expresa en homocigosis aa.','[{"text":"aa","correct":true},{"text":"AA","correct":false},{"text":"Aa","correct":false},{"text":"AA y Aa por definición","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division',5,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance","https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000036','d7301030-2026-4000-8001-000000000004','En Aa por Aa, ¿qué probabilidad tiene aa para cada descendiente en el modelo mendeliano?','El cuadro de combinaciones da AA, Aa, Aa y aa: una de cuatro es aa.','[{"text":"0 %","correct":false},{"text":"50 %","correct":false},{"text":"100 %","correct":false},{"text":"25 %","correct":true}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division',6,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance","https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000037','d7301030-2026-4000-8001-000000000004','Una pareja Aa tiene cuatro descendientes. ¿Qué implica la probabilidad del 25 % para aa?','La probabilidad se aplica a cada combinación, no garantiza una distribución exacta en pocos casos.','[{"text":"El cuarto será aa obligatoriamente","correct":false},{"text":"Ninguno puede ser aa si el primero no lo fue","correct":false},{"text":"Cada descendiente tiene esa probabilidad; no impone un reparto familiar exacto","correct":true},{"text":"Exactamente uno será aa obligatoriamente","correct":false}]'::jsonb,2,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division',7,'clinical_case','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance","https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000038','d7301030-2026-4000-8001-000000000004','¿Qué describe la codominancia?','En codominancia ambos alelos se expresan, como IA e IB en el grupo AB.','[{"text":"Ausencia de cromosomas","correct":false},{"text":"Expresión de ambos alelos en el fenotipo","correct":true},{"text":"Desaparición de ambos alelos","correct":false},{"text":"Dominancia completa de uno en todos los casos","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division',8,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance","https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000039','d7301030-2026-4000-8001-000000000004','¿Qué significa que un rasgo sea poligénico?','Muchos rasgos dependen de varios genes y pueden estar influidos por el ambiente.','[{"text":"Que intervienen varios genes","correct":true},{"text":"Que depende de un único alelo siempre","correct":false},{"text":"Que no tiene relación con el ADN","correct":false},{"text":"Que solo aparece en gametos","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division',9,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance","https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000040','d7301030-2026-4000-8001-000000000004','¿Qué afirmación sobre dominante es correcta?','La dominancia es una relación de expresión; no equivale a frecuencia o valor biológico.','[{"text":"Significa siempre más frecuente","correct":false},{"text":"Significa siempre beneficioso","correct":false},{"text":"Significa que no puede heredarse","correct":false},{"text":"Describe una relación de expresión entre alelos en un modelo","correct":true}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division',10,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/28-7-patterns-of-inheritance","https://openstax.org/books/anatomy-and-physiology-2e/pages/3-5-cell-growth-and-division"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_topics (id,unit_id,name,slug,description,display_order,content_language,translation_mode,is_active) VALUES ('d7301030-2026-4000-8001-000000000005','d7301030-2026-4000-8000-000000000002','Inmunidad: barreras, respuesta innata y adaptativa','es-s1-final-immune','Comparar rapidez, especificidad y memoria; relacionar barreras, inflamación y linfocitos sin confundir sus funciones.',34,'es','none',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_lessons (id,topic_id,title,summary,content,key_points,source_files,display_order,validation_status,is_published) VALUES ('d7301030-2026-4000-8002-000000000005','d7301030-2026-4000-8001-000000000005','Inmunidad: barreras, respuesta innata y adaptativa','Comparar rapidez, especificidad y memoria; relacionar barreras, inflamación y linfocitos sin confundir sus funciones.','### Objetivos

Comparar rapidez, especificidad y memoria; relacionar barreras, inflamación y linfocitos sin confundir sus funciones.

### Primera protección

Piel y mucosas dificultan la entrada de microorganismos. La defensa incluye barreras físicas y químicas. La respuesta innata reconoce patrones y puede actuar con rapidez; la inflamación facilita reclutamiento celular y respuesta local, aunque puede producir síntomas y daño.

### Respuesta específica

La inmunidad adaptativa se organiza frente a antígenos concretos e incluye linfocitos T y B. Las células plasmáticas derivadas de B producen anticuerpos. Los T colaboradores coordinan respuestas y los citotóxicos pueden destruir células infectadas.

### Memoria y coordinación

La respuesta adaptativa secundaria puede ser más rápida y eficaz gracias a memoria inmunitaria. Innata y adaptativa cooperan, no son circuitos aislados. Una respuesta inmunitaria no equivale siempre a infección: hay reacciones alérgicas y autoinmunes. Conocer el mecanismo no permite diagnosticar una enfermedad por un síntoma aislado.

### Conceptos para explicar sin mirar

- La piel íntegra dificulta la entrada de numerosos microorganismos.
- La inmunidad innata actúa con rapidez y reconoce patrones compartidos por amenazas.
- La adaptativa incluye respuestas específicas y memoria frente a exposiciones previas.
- Los linfocitos B pueden diferenciarse en células plasmáticas secretoras de anticuerpos.
- Los T citotóxicos participan en eliminar células infectadas u otras células diana.
- Los T colaboradores coordinan respuestas e influyen en otras células inmunitarias.
- Las células de memoria permiten respuestas adaptativas secundarias más rápidas.
- La inmunidad innata ayuda a activar y orientar respuestas adaptativas.
- La fagocitosis permite a determinadas células capturar material y contribuir a su eliminación.
- La inflamación puede aparecer en distintos contextos y necesita valoración conjunta.

### Comprobación

Resuelve el cuestionario sin consultar el texto. Justifica tu elección y explica por qué las otras opciones no encajan. Si confundes dos conceptos, compáralos en una frase y vuelve a probar en otra sesión.

Material original de entrenamiento; no es un examen ni un apunte oficial de UVic.','["Primera protección","Respuesta específica","Memoria y coordinación"]'::jsonb,'[{"url":"https://www.uvic.cat/es/assignatura/4405","label":"UVic-UCC · plan docente y alcance curricular","verified_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/21-2-barrier-defenses-and-the-innate-immune-response","label":"OpenStax · texto académico abierto","verified_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/21-3-the-adaptive-immune-response-t-lymphocytes-and-their-functional-types","label":"OpenStax · texto académico abierto","verified_at":"2026-10-30"}]'::jsonb,1,'source_validated',true) ON CONFLICT(id) DO NOTHING;
