INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000061','d7301030-2026-4000-8001-000000000007','En inspiración tranquila, ¿qué cambio favorece la entrada de aire?','El aire entra cuando existe un gradiente de presión desde el exterior hacia los alvéolos.','[{"text":"Presión alveolar inferior a la atmosférica","correct":true},{"text":"Presión alveolar siempre superior a la atmosférica","correct":false},{"text":"Ausencia de diferencias de presión","correct":false},{"text":"Cierre completo de la vía aérea","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/22-3-the-process-of-breathing · https://openstax.org/books/anatomy-and-physiology-2e/pages/22-4-gas-exchange',1,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/22-3-the-process-of-breathing","https://openstax.org/books/anatomy-and-physiology-2e/pages/22-4-gas-exchange"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
