INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000069','d7301030-2026-4000-8001-000000000007','En condiciones habituales, ¿en qué dirección pasa el oxígeno en el pulmón?','El gradiente alveolocapilar habitual favorece la entrada de oxígeno a la sangre.','[{"text":"Del aire alveolar hacia la sangre","correct":true},{"text":"De la sangre hacia el aire exclusivamente","correct":false},{"text":"Del uréter al alvéolo","correct":false},{"text":"Del miocardio a la tráquea directamente","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/22-3-the-process-of-breathing · https://openstax.org/books/anatomy-and-physiology-2e/pages/22-4-gas-exchange',9,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/22-3-the-process-of-breathing","https://openstax.org/books/anatomy-and-physiology-2e/pages/22-4-gas-exchange"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000070','d7301030-2026-4000-8001-000000000007','Una zona recibe aire pero casi no recibe sangre. ¿Qué componente limita allí el intercambio?','El aire sin flujo sanguíneo suficiente no permite un intercambio eficaz con la circulación.','[{"text":"Solo conducción nasal","correct":false},{"text":"Solo fonación","correct":false},{"text":"La ausencia obligatoria de ventilación","correct":false},{"text":"Perfusión","correct":true}]'::jsonb,2,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/22-3-the-process-of-breathing · https://openstax.org/books/anatomy-and-physiology-2e/pages/22-4-gas-exchange',10,'clinical_case','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/22-3-the-process-of-breathing","https://openstax.org/books/anatomy-and-physiology-2e/pages/22-4-gas-exchange"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_topics (id,unit_id,name,slug,description,display_order,content_language,translation_mode,is_active) VALUES ('d7301030-2026-4000-8001-000000000008','d7301030-2026-4000-8000-000000000002','Aparato digestivo: trayecto, secreciones y absorción','es-s1-final-digest','Seguir el trayecto de los alimentos y distinguir digestión mecánica, química y absorción; relacionar intestino, hígado y páncreas.',37,'es','none',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_lessons (id,topic_id,title,summary,content,key_points,source_files,display_order,validation_status,is_published) VALUES ('d7301030-2026-4000-8002-000000000008','d7301030-2026-4000-8001-000000000008','Aparato digestivo: trayecto, secreciones y absorción','Seguir el trayecto de los alimentos y distinguir digestión mecánica, química y absorción; relacionar intestino, hígado y páncreas.','### Objetivos

Seguir el trayecto de los alimentos y distinguir digestión mecánica, química y absorción; relacionar intestino, hígado y páncreas.

### Órganos y trayecto

Boca, faringe, esófago, estómago, intestino delgado e intestino grueso forman un recorrido continuo. Hígado, vesícula y páncreas colaboran mediante secreciones, pero el alimento no atraviesa su interior como atraviesa el tubo digestivo. El peristaltismo favorece el avance del contenido.

### Descomponer y absorber

La digestión mecánica fragmenta y mezcla; la química rompe moléculas mediante reacciones, frecuentemente enzimáticas. La absorción transfiere productos hacia sangre o linfa. La mayor parte de la absorción de nutrientes ocurre en intestino delgado. La digestión de carbohidratos empieza en boca y la de proteínas se inicia de forma importante en estómago.

### Secreciones y circulación

La bilis es producida por el hígado y almacenada en vesícula; ayuda a emulsificar grasas, pero no es una enzima. El páncreas exocrino vierte enzimas al intestino. La sangre del tubo digestivo pasa en gran parte por la circulación portal hepática antes de retornar al corazón. Los lípidos de cadena larga siguen especialmente la vía linfática.

### Conceptos para explicar sin mirar

- El esófago es parte del tubo digestivo; los otros órganos colaboran mediante secreciones.
- El intestino delgado es el principal lugar de absorción de nutrientes.
- La digestión mecánica modifica tamaño y mezcla; la química descompone moléculas.
- La absorción incorpora sustancias al medio interno a través de la pared intestinal.
- La bilis se produce en hígado y puede almacenarse en vesícula.
- La vesícula almacena y concentra bilis producida por el hígado.
- La porción exocrina pancreática aporta enzimas por conductos al tubo digestivo.
- La bilis facilita la emulsificación y la acción digestiva sobre lípidos, pero no es una enzima.
- La amilasa salival participa en la digestión inicial del almidón.
- La circulación portal lleva nutrientes absorbidos hacia el hígado para su procesamiento.

### Comprobación

Resuelve el cuestionario sin consultar el texto. Justifica tu elección y explica por qué las otras opciones no encajan. Si confundes dos conceptos, compáralos en una frase y vuelve a probar en otra sesión.

