INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000072','d7301030-2026-4000-8001-000000000008','¿Dónde se absorbe la mayor parte de los nutrientes?','El intestino delgado es el principal lugar de absorción de nutrientes.','[{"text":"Esófago","correct":false},{"text":"Boca","correct":false},{"text":"Vesícula biliar","correct":false},{"text":"Intestino delgado","correct":true}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/23-1-overview-of-the-digestive-system · https://openstax.org/books/anatomy-and-physiology-2e/pages/23-7-chemical-digestion-and-absorption-a-closer-look',2,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/23-1-overview-of-the-digestive-system","https://openstax.org/books/anatomy-and-physiology-2e/pages/23-7-chemical-digestion-and-absorption-a-closer-look"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
