INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000090','d7301030-2026-4000-8001-000000000009','¿Qué función, además de eliminar desechos, corresponde al riñón?','El riñón regula componentes del medio interno además de formar orina.','[{"text":"Producir toda la bilis","correct":false},{"text":"Realizar intercambio con aire alveolar","correct":false},{"text":"Sintetizar anticuerpos como función principal","correct":false},{"text":"Contribuir al equilibrio ácido-base y de electrolitos","correct":true}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/25-4-microscopic-anatomy-of-the-kidney · https://openstax.org/books/anatomy-and-physiology-2e/pages/25-5-physiology-of-urine-formation',10,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/25-4-microscopic-anatomy-of-the-kidney","https://openstax.org/books/anatomy-and-physiology-2e/pages/25-5-physiology-of-urine-formation"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_topics (id,unit_id,name,slug,description,display_order,content_language,translation_mode,is_active) VALUES ('d7301030-2026-4000-8001-000000000010','d7301030-2026-4000-8000-000000000002','Sistema endocrino: receptores, ejes y glucemia','es-s1-final-endocrine','Relacionar glándula, hormona y célula diana; comprender la regulación por retroalimentación sin memorizar listas aisladas.',39,'es','none',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_lessons (id,topic_id,title,summary,content,key_points,source_files,display_order,validation_status,is_published) VALUES ('d7301030-2026-4000-8002-000000000010','d7301030-2026-4000-8001-000000000010','Sistema endocrino: receptores, ejes y glucemia','Relacionar glándula, hormona y célula diana; comprender la regulación por retroalimentación sin memorizar listas aisladas.','### Objetivos

Relacionar glándula, hormona y célula diana; comprender la regulación por retroalimentación sin memorizar listas aisladas.

### Señal y receptor

Una hormona puede circular por sangre sin actuar en todas las células: la respuesta depende de receptores y mecanismos celulares. Hormonas peptídicas suelen usar receptores de membrana; las esteroideas atraviesan membranas y se unen a receptores intracelulares.

### Glándulas y ejes

La hipófisis anterior produce hormonas tróficas como TSH y ACTH. La neurohipófisis libera ADH y oxitocina sintetizadas en el hipotálamo. Hormonas tiroideas influyen en metabolismo; PTH participa en regulación del calcio. Corteza y médula suprarrenales tienen secreciones diferentes.

### Páncreas y regulación

Las células beta secretan insulina y las alfa glucagón. La insulina favorece el descenso de glucemia mediante captación y almacenamiento; el glucagón contribuye a elevarla, especialmente mediante acciones hepáticas. Un aumento de glucemia estimula normalmente insulina. Este es un ejemplo de regulación; no permite diagnosticar ni indicar un tratamiento a partir de una pregunta de repaso.

### Conceptos para explicar sin mirar

- La especificidad hormonal depende de receptores y de la capacidad de respuesta celular.
- Muchas hormonas peptídicas se unen a receptores de membrana e inician señalización intracelular.
- La TSH hipofisaria estimula la secreción de hormonas tiroideas.
- La ADH se sintetiza en hipotálamo y se libera por neurohipófisis.
- Las células beta de los islotes pancreáticos producen insulina.
- Las células alfa de los islotes producen glucagón.
- La glucemia elevada estimula células beta y la secreción de insulina.
- El glucagón favorece procesos hepáticos que aumentan glucosa disponible en sangre.
- La hormona paratiroidea participa en la regulación del calcio y contribuye a elevar su nivel sanguíneo.
- Las regiones suprarrenales tienen poblaciones y secreciones diferentes.

### Comprobación

Resuelve el cuestionario sin consultar el texto. Justifica tu elección y explica por qué las otras opciones no encajan. Si confundes dos conceptos, compáralos en una frase y vuelve a probar en otra sesión.

Material original de entrenamiento; no es un examen ni un apunte oficial de UVic.','["Señal y receptor","Glándulas y ejes","Páncreas y regulación"]'::jsonb,'[{"url":"https://www.uvic.cat/es/assignatura/4405","label":"UVic-UCC · plan docente y alcance curricular","verified_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/17-2-hormones","label":"OpenStax · texto académico abierto","verified_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/17-9-the-endocrine-pancreas","label":"OpenStax · texto académico abierto","verified_at":"2026-10-30"}]'::jsonb,1,'source_validated',true) ON CONFLICT(id) DO NOTHING;
