INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000109','d7301030-2026-4000-8001-000000000011','Un esquema representa un ciclo de 28 días. ¿Qué lectura es correcta?','Los ciclos presentan variabilidad y no deben interpretarse como un calendario universal.','[{"text":"Es un modelo orientativo y no una duración obligatoria para todas las personas","correct":true},{"text":"Todos los ciclos deben durar exactamente 28 días","correct":false},{"text":"La ovulación ocurre siempre el mismo día sin variación","correct":false},{"text":"El esquema sustituye cualquier valoración individual","correct":false}]'::jsonb,2,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/27-1-anatomy-and-physiology-of-the-testicular-reproductive-system · https://openstax.org/books/anatomy-and-physiology-2e/pages/27-2-anatomy-and-physiology-of-the-ovarian-reproductive-system',9,'clinical_case','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/27-1-anatomy-and-physiology-of-the-testicular-reproductive-system","https://openstax.org/books/anatomy-and-physiology-2e/pages/27-2-anatomy-and-physiology-of-the-ovarian-reproductive-system"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
