INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000155','d7301030-2026-4000-8001-000000000016','Una persona evita pedir ayuda por una norma que asocia hacerlo con debilidad. ¿Qué factor puede influir?','Las normas sociales pueden influir en búsqueda de ayuda y conductas de salud.','[{"text":"Normas sociales de género","correct":true},{"text":"Solo filtración renal","correct":false},{"text":"Solo la forma de una válvula","correct":false},{"text":"Ausencia obligatoria de necesidad sanitaria","correct":false}]'::jsonb,2,'Entrenamiento original · https://www.who.int/health-topics/gender',5,'clinical_case','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://www.who.int/health-topics/gender"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
