INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('d7301030-2026-4000-8003-000000000170','d7301030-2026-4000-8001-000000000017','¿Qué puede indicar una reevaluación sin eficacia evidente?','La revisión de resultados puede orientar ajustes, finalización o derivación según contexto.','[{"text":"Continuar siempre sin cambios","correct":false},{"text":"Omitir los resultados","correct":false},{"text":"Asegurar que el diagnóstico nunca puede revisarse","correct":false},{"text":"Revisar el plan, sus objetivos y la pertinencia de continuar o derivar","correct":true}]'::jsonb,1,'Entrenamiento original · https://world.physio/history · https://world.physio/sites/default/files/2024-06/PS2023-Description-es.pdf · https://www.fisioterapeutes.cat/es/comunicacion/noticias/2026/1/15/libro-la-fisioterapia-cataluna-1957-2025-etnografia-una-profesion-ya-disponible-gratuitamente-web-colegi',10,'mcq','{"content_batch":"es-s1-final-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","verified_at":"2026-10-30","source_urls":["https://world.physio/history","https://world.physio/sites/default/files/2024-06/PS2023-Description-es.pdf"]}'::jsonb,'source_validated',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_topics (id,unit_id,name,slug,description,display_order,content_language,translation_mode,is_active) VALUES ('d7301030-2026-4000-8001-000000000101','d7301030-2026-4000-8000-000000000001','Anatomía I: organización, tejidos y membranas','es-s1-base-anat','Relaciona células, tejidos y órganos; distingue los cuatro tejidos básicos y las membranas corporales.',1,'es','none',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_lessons (id,topic_id,title,summary,content,key_points,source_files,display_order,validation_status,is_published) VALUES ('d7301030-2026-4000-8002-000000000101','d7301030-2026-4000-8001-000000000101','Anatomía I: organización, tejidos y membranas','Relaciona células, tejidos y órganos; distingue los cuatro tejidos básicos y las membranas corporales.','### Objetivos de repaso

Distinguir célula, tejido y órgano; reconocer las funciones generales de los cuatro tejidos básicos; diferenciar una membrana celular de una membrana tisular.

### De la célula al órgano

Las células son unidades vivas que se especializan. Un tejido es una agrupación organizada de células y material extracelular que participa en funciones relacionadas. Un órgano combina varios tejidos: nombrar un órgano no equivale a identificar un único tejido. La histología estudia los tejidos al microscopio.

### Los cuatro tejidos básicos

El epitelial recubre superficies, reviste cavidades y forma glándulas. El conectivo sostiene, une y protege; su matriz extracelular tiene un papel destacado. El muscular produce fuerza mediante la contracción: comprende músculo esquelético, cardíaco y liso. El nervioso permite la comunicación mediante señales electroquímicas. Clasifica por estructura y función, sin suponer que un órgano contiene un solo tipo.

### Membranas tisulares

Las mucosas revisten vías que comunican con el exterior, como el tubo digestivo. Las serosas revisten cavidades internas cerradas y recubren órganos; ayudan a reducir el rozamiento. Pleura, pericardio y peritoneo son ejemplos de serosas. La membrana cutánea es la piel. Las membranas sinoviales son membranas de tejido conectivo relacionadas con articulaciones móviles. Estas láminas de tejidos son distintas de la membrana plasmática de una célula.

### Primeras bases de embriología

Las tres capas germinales son ectodermo, mesodermo y endodermo. El tejido nervioso deriva principalmente del ectodermo; el muscular, del mesodermo. El epitelio puede tener origen en las tres capas, según su localización: «todo epitelio procede del ectodermo» es una simplificación incorrecta.

### Aplicación y errores frecuentes

En una pared de un órgano pueden coexistir revestimiento epitelial, soporte conectivo, músculo y estructuras nerviosas. Identificar el tejido exige precisar qué componente se observa.
No confundas membrana plasmática con mucosa, ni tejido muscular con órgano completo.

### Autoevaluación

Explica qué diferencia un tejido de un órgano y compara mucosa, serosa y sinovial con un ejemplo de cada una.

Material de repaso original basado en las fuentes enlazadas; no es una reproducción del curso ni un examen oficial.','["Cuatro tejidos: epitelial, conectivo, muscular y nervioso.","Un órgano combina varios tejidos.","Mucosa: vías abiertas al exterior; serosa: cavidades cerradas.","La membrana sinovial es de tejido conectivo.","Ectodermo, mesodermo y endodermo son capas germinales."]'::jsonb,'[{"url":"https://www.uvic.cat/es/assignatura/4402","label":"UVic-UCC · Plan docente · alcance de la asignatura","verified_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues","label":"OpenStax · Texto académico abierto · fundamento del repaso","verified_at":"2026-10-30"}]'::jsonb,1,'source_validated',true) ON CONFLICT(id) DO NOTHING;
UPDATE public.curriculum_quiz_questions SET topic_id='d7301030-2026-4000-8001-000000000101',display_order=display_order-1000,updated_at=now() WHERE id IN ('b7301030-2026-4000-8003-000000000001','b7301030-2026-4000-8003-000000000002','b7301030-2026-4000-8003-000000000003','b7301030-2026-4000-8003-000000000004','b7301030-2026-4000-8003-000000000005','b7301030-2026-4000-8003-000000000006','b7301030-2026-4000-8003-000000000007','b7301030-2026-4000-8003-000000000008','b7301030-2026-4000-8003-000000000009','b7301030-2026-4000-8003-000000000010') AND topic_id='e784bdd3-43aa-4c2a-a61f-32bd4b93192b';
INSERT INTO public.curriculum_topics (id,unit_id,name,slug,description,display_order,content_language,translation_mode,is_active) VALUES ('d7301030-2026-4000-8001-000000000102','d7301030-2026-4000-8000-000000000002','Fisiología I: membrana y transporte celular','es-s1-base-phys','Comprende la permeabilidad selectiva y diferencia difusión, ósmosis y transporte activo.',1,'es','none',true) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.curriculum_lessons (id,topic_id,title,summary,content,key_points,source_files,display_order,validation_status,is_published) VALUES ('d7301030-2026-4000-8002-000000000102','d7301030-2026-4000-8001-000000000102','Fisiología I: membrana y transporte celular','Comprende la permeabilidad selectiva y diferencia difusión, ósmosis y transporte activo.','### Objetivos de repaso

Explicar por qué una membrana selecciona qué sustancias la atraviesan y comparar los mecanismos básicos de transporte. Este bloque desarrolla la fisiología celular incluida en Fisiología I; no resume por sí solo toda la asignatura.

### Estructura de la membrana

La membrana plasmática delimita el interior celular. Está formada principalmente por una bicapa de fosfolípidos con proteínas y colesterol. Las cabezas hidrófilas se orientan hacia los medios acuosos; las colas hidrófobas quedan enfrentadas hacia el interior de la bicapa. La membrana es dinámica, no una pared rígida.

### Permeabilidad selectiva

Moléculas pequeñas no polares como oxígeno y dióxido de carbono pueden atravesar la bicapa. Los iones y muchas sustancias hidrosolubles requieren proteínas para cruzarla. Un canal crea una vía selectiva; un transportador se une a una sustancia y cambia de conformación. No todas las sustancias utilizan el mismo mecanismo.

### Transporte pasivo

No exige gasto directo de energía celular para impulsar el transporte. La difusión simple desplaza partículas a favor de su gradiente de concentración. La difusión facilitada también es pasiva, aunque utilice proteínas: «usa proteína» no significa «usa ATP».
La ósmosis es el movimiento neto de agua a través de una membrana selectivamente permeable. En condiciones comparables, el agua se desplaza hacia el lado con mayor concentración de solutos que no pueden atravesar la membrana.

### Transporte activo

Requiere energía y puede mover sustancias en contra de su gradiente. En el transporte activo primario la proteína utiliza ATP directamente. En el secundario, el movimiento de una sustancia aprovecha el gradiente de otra; la energía procede indirectamente de un gradiente mantenido por mecanismos activos.

### Aplicación razonada

Si un soluto cruza mediante una proteína a favor de su gradiente sin aporte energético directo, puede ser difusión facilitada. Para clasificar un transporte pregunta: ¿qué se mueve?, ¿en qué dirección respecto al gradiente?, ¿qué proteína interviene?, ¿de dónde procede la energía?

### Errores frecuentes

Ósmosis describe agua, no cualquier soluto. Difusión facilitada no es sinónimo de transporte activo. Un gradiente es una diferencia, no una estructura.

### Autoevaluación

Compara difusión simple, difusión facilitada y transporte activo con los criterios anteriores.

Material de entrenamiento original basado en fuentes; no es un examen oficial.','["Bicapa con cabezas hidrófilas y colas hidrófobas.","Difusión facilitada: proteína y transporte pasivo.","Ósmosis: movimiento neto de agua.","Transporte activo primario: uso directo de ATP.","Transporte activo secundario: acoplamiento a otro gradiente."]'::jsonb,'[{"url":"https://www.uvic.cat/es/assignatura/4405","label":"UVic-UCC · Plan docente · alcance de la asignatura","verified_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane","label":"OpenStax · Texto académico abierto · fundamento del repaso","verified_at":"2026-10-30"}]'::jsonb,1,'source_validated',true) ON CONFLICT(id) DO NOTHING;
